// var dInfo = null;
var loadingInfo = null;
var bufferArray=[];
var depthColors = [];
var loadType = 1; // 水深 2：水位
self.onmessage = function (evt) {
  // debugger
  //if (!evt.data.urlInfo) {
  //    return;
  //}
  // console.log('evt.data.loadInfo', evt.data.loadInfo);
  switch (evt.data.msg) {
    case 'load':
      loadingInfo = evt.data.loadInfo;
      depthColors = evt.data.loadInfo.depthColors?evt.data.loadInfo.depthColors:vColors;
      loadType = evt.data.loadInfo.loadType;
      loadData(evt.data.loadInfo);
      break;
    case 'stopload':
      stopLoad();
      break;
  }
};
function loadData(loadInfo) {
  try {
    let e = new XMLHttpRequest();
    e.onreadystatechange = function () {
      if (e.readyState == 4 && e.status == 200) {
        if (loadInfo == loadingInfo) {
          bufferArray.length=0;
          var d = {};
          d = JSON.parse(e.response);
          if(d){
            switch(loadInfo.parsType){
              case 0:
                d=parsData0(d);
                break;
              default:
                d=parsData0(d);
                break;
            }

            // var vs = covData(d);
            // d = {
            //   colors: new Uint8Array(getDepthColors(vs.svs)),//水深颜色
            //   colors2: new Uint8Array(getSurfaceColors(pos)),//水位颜色
            //   colors3: new Uint8Array(getFlowColors(vs.fvs)),//流速颜色
            //   pos: new Float64Array(crdArr2c3(pos, 3)),
            //   // values:vArr,
            // };

            // bufferArray.push(d.colors.buffer);
            // bufferArray.push(d.colors2.buffer);
            // bufferArray.push(d.colors3.buffer);
            // bufferArray.push(d.pos.buffer);

            d.loadInfo = loadInfo;
            d.msg = 'success';
            self.postMessage(d,bufferArray);
          } else {
            self.postMessage({ loadInfo: loadInfo, msg: "success" });
          }
        }
      }
    };
    e.open('GET', loadInfo.dataUrl, false);
    e.send(null);
  } catch (e) {
    if (loadInfo == loadingInfo) {
      self.postMessage({ loadInfo: loadInfo, msg: 'error' });
    }
  }
}

function parsData0(obj){
  var vs = covData(obj);
  obj = {
    colors: new Uint8Array(getDepthColors(vs.svs)),//水深颜色
    colors2: new Uint8Array(getSurfaceColors(pos)),//水位颜色
    colors3: new Uint8Array(getFlowColors(vs.fvs)),//流速颜色
    pos: new Float64Array(crdArr2c3(pos, 3)),
    // values:vArr,
  };
  bufferArray.push(obj.colors.buffer);
  bufferArray.push(obj.colors2.buffer);
  bufferArray.push(obj.colors3.buffer);
  bufferArray.push(obj.pos.buffer);
  return obj;
}


function stopLoad() {
  loadingInfo = null;
}
