// }
function covData(arr) {
  var v = 0;
  var fv=0;
  var nArr = [];
  var fArr=[];
  let num = arr.length / 5;
  let ws=0;

  for (var i = 0; i < num; i++) {
    // for (var i = 0; i < p_tins.length; i++) {
    // v = getAverageValue(arr, p_tins[i]);

    ws=arr[i * 5 + 0];
    if (isNaN(ws)) {
      ws = 0;
    }
    v = arr[i * 5 + 2];
    if (isNaN(v)) {
      v = 0;
    }
    fv=arr[i * 5 + 3];
    if (isNaN(fv)) {
      fv = 0;
    }
    ////////////////////////////////////////////////////////////////
    // if (pos[i * 3 + 2] < 295) {
      // v = Math.random() * 8; //测试用，水面随机取0到8；
      // fv= Math.random() * 2; //测试用，水面随机取0到2；
    // }
    ////////////////////////////////////////////////////////////////
    // pos[i * 3 + 2] = pos[i * 3 + 2] + v;
    // if(v>0){
      pos[i * 3 + 2] = ws + 0;
    // }

    nArr.push(v);
    fArr.push(fv);
  }
  return {
    svs:nArr,
    fvs:fArr,
  };
}
function toC3Pos(crds) {}
function getAverageValue(vs, ins) {
  // debugger;
  var v = 0; //水深
  // var dep = 0; //水底高程
  // var dep2 = 0; //水面高程
  for (var i = 0; i < ins.length; i++) {
    v += vs[ins[i] * 5 + 2];
    // dep += Math.abs(vs[ins[i] * 5 + 1]); //
    // dep2 += Math.abs(vs[ins[i] * 5 + 0]);
    //
  }
  v = v / ins.length; //取均值
  // dep = dep / ins.length; //取均值
  // dep2 = dep2 / ins.length; //取均值
  return v;
}
function getColorsGroup(groups,index) {
  if(index<0){
    //console.info("图例颜色有错");
    index=0;
  }
  if(index>=groups.length){
    index=0;
    //console.info("图例颜色有错,颜色类别组不足"+groups.length);
  }
  return groups[index];
}
function getDepthColors(vArr) {
  //按水深获取颜色
  let colors = null;
  if (vArr) {
    colors = [];
    for (let i = 0; i < vArr.length; i++) {
      colors.push(...getDepthColor(vArr[i]));
    }
  }
  return colors;
}
function getDepthColor(depth) {
  let vcs=null;
  vcs=getColorsGroup(depthColors,0);
  for (var i = 0; i < vcs.length; i++) {
    if (depth < 1.0000001E-20) {
      return [92, 9, 252, 0];
    }
    if (depth >= vcs[i].depth[0] && depth < vcs[i].depth[1]) {
      return vcs[i].rgba;
    }
  }
  return vcs[0].rgba;
}

function getSurfaceColors(vArr) {
  //按水位获取颜色
  let colors = null;
  if (vArr) {
    colors = [];
    var num = vArr.length / 3;
    for (let i = 0; i < num; i++) {
      colors.push(...getSurfaceColor(vArr[i * 3 + 2]));
    }
  }
  return colors;
}
function getSurfaceColor(depth) {
  let vcs=null;
  vcs=getColorsGroup(depthColors,1);
  for (var i = 0; i < vcs.length; i++) {
    if (depth < 1.0000001E-20) {
      return [92, 9, 252, 0];
    }
    if (depth >= vcs[i].depth[0] && depth < vcs[i].depth[1]) {
      return vcs[i].rgba;
    }
  }
  return [92, 9, 252, 0];
}

function getFlowColors(vArr) {
  //按流速获取颜色
  let colors = null;
  if (vArr) {
    colors = [];
    for (let i = 0; i < vArr.length; i++) {
      colors.push(...getFlowColor(vArr[i]));
    }
  }
  return colors;
}
function getFlowColor(depth) {
  let vcs=null;
  vcs=getColorsGroup(depthColors,2);
  for (var i = 0; i < vcs.length; i++) {
    if (depth < 1.0000001E-20) {
      return [92, 9, 252, 0];
    }
    if (depth >= vcs[i].depth[0] && depth < vcs[i].depth[1]) {
      return vcs[i].rgba;
    }
  }
  return [92, 9, 252, 0];
}

RADIANS_PER_DEGREE = Math.PI / 180.0;
RadiiSquared = { x: 40680631590769, y: 40680631590769, z: 40408299984661.445 };
function crd2c3(x, y, h) {
  var lon = x * RADIANS_PER_DEGREE;
  var lat = y * RADIANS_PER_DEGREE;
  var cosLatitude = Math.cos(lat);
  var scratchN = {
    x: cosLatitude * Math.cos(lon),
    y: cosLatitude * Math.sin(lon),
    z: Math.sin(lat)
  };
  var scratchK = {
    x: RadiiSquared.x * scratchN.x,
    y: RadiiSquared.y * scratchN.y,
    z: RadiiSquared.z * scratchN.z
  };
  var dot = scratchN.x * scratchK.x + scratchN.y * scratchK.y + scratchN.z * scratchK.z;
  var gamma = Math.sqrt(dot);
  scratchK.x = scratchK.x / gamma;
  scratchK.y = scratchK.y / gamma;
  scratchK.z = scratchK.z / gamma;
  if (!h) {
    h = 1;
  }

  scratchN.x = scratchN.x * h;
  scratchN.y = scratchN.y * h;
  scratchN.z = scratchN.z * h;

  var c3 = {
    x: scratchK.x + scratchN.x,
    y: scratchK.y + scratchN.y,
    z: scratchK.z + scratchN.z
  };
  return c3;
}
function crdArr2c3(crds, vnum) {
  var arr = null;
  if (crds && crds.length > 0) {
    arr = [];
    var c3 = null;
    for (var i = 0; i < crds.length; i += vnum) {
      if (vnum == 3) {
        // c3=crd2c3(crds[i],crds[i+1],crds[i+2]+1.4);
        c3 = crd2c3(crds[i], crds[i + 1], crds[i + 2] + 0.2);
      } else {
        c3 = crd2c3(crds[i], crds[i + 1], 0.1);
      }
      arr.push(c3.x);
      arr.push(c3.y);
      arr.push(c3.z);
    }
  }
  return arr;
}

